/* =====================================================================
   Manufacturer Master - OLD data copy - 2026-11-13
   Source : OLD HIS DEMO_HIS_NEW.dbo.ManufacturerMaster (1,011 rows, exported 2026-11-13)
   Target : GWT_HIS_API.dbo.ManufacturerMaster
   Run AFTER 2026-11-13_ManufacturerMaster.sql. Re-runnable: inserts only ids that are not present yet.
   OLD ids are kept (IDENTITY_INSERT) so that OLD store items can later be migrated without remapping ManufacturerId
   (owner decision 2026-11-13, Store_Item_Master_Build_Spec 6.5).
   Note: CreatedBy / LastModifiedBy are OLD user ids, copied as they are.
   ===================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

IF OBJECT_ID('tempdb..#mfr') IS NOT NULL DROP TABLE #mfr;
CREATE TABLE #mfr (HospId int, ManufacturerId int, ManufacturerName nvarchar(256), IsActive int, CreatedBy int, CreatedOn datetime,
                   LastModifiedBy int, LastModifiedOn datetime, IpAddress nvarchar(20), UniqueId nvarchar(50));


SET IDENTITY_INSERT dbo.ManufacturerMaster ON;
SELECT s.HospId, s.ManufacturerId, s.ManufacturerName, s.IsActive, s.CreatedBy, s.CreatedOn, s.LastModifiedBy, s.LastModifiedOn, s.IpAddress, s.UniqueId
FROM #mfr s
WHERE NOT EXISTS (SELECT 1 FROM dbo.ManufacturerMaster t WHERE t.ManufacturerId = s.ManufacturerId);
PRINT CAST(@@ROWCOUNT AS varchar) + ' manufacturer(s) copied.';
SET IDENTITY_INSERT dbo.ManufacturerMaster OFF;

-- keep the identity seed above the highest copied id
DECLARE @maxId int = (SELECT ISNULL(MAX(ManufacturerId), 0) FROM dbo.ManufacturerMaster);
DBCC CHECKIDENT ('dbo.ManufacturerMaster', RESEED, @maxId) WITH NO_INFOMSGS;

-- names that differ only by spaces/case (the unique-name rule will block editing one of each pair; merge later)
SELECT LTRIM(RTRIM(ManufacturerName)) AS DuplicateName, COUNT(*) AS Cnt, STRING_AGG(CAST(ManufacturerId AS varchar), ',') AS Ids
FROM dbo.ManufacturerMaster GROUP BY LTRIM(RTRIM(ManufacturerName)) HAVING COUNT(*) > 1;

DROP TABLE #mfr;
COMMIT;
GO
